import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { Interview, interviewApplicantName, interviewCalendarIso, interviewJobTitle } from '../../types/interview.types';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { useMemo } from 'react';
import EyeIcon from '@/components/icons/marketing/EyeIcon';

interface InterviewPreviewProps {
    interview: Interview | null;
    openUpdateDialog: boolean;
    setopenUpdateDialog: (open: boolean) => void;
}

export default function InterviewPreview({
    interview,
    openUpdateDialog,
    setopenUpdateDialog,
}: InterviewPreviewProps) {
    const { dateValue, timeValue, levelLabel, workTypeLabel } = useMemo(() => {
        if (!interview) {
            return { dateValue: '', timeValue: '', levelLabel: '', workTypeLabel: '' };
        }
        const iso = interviewCalendarIso(interview);
        if (!iso) {
            return { dateValue: '', timeValue: '', levelLabel: '', workTypeLabel: '' };
        }
        const parsed = new Date(iso);
        if (Number.isNaN(parsed.getTime())) {
            return { dateValue: '', timeValue: '', levelLabel: '', workTypeLabel: '' };
        }
        const y = parsed.getFullYear();
        const m = String(parsed.getMonth() + 1).padStart(2, '0');
        const d = String(parsed.getDate()).padStart(2, '0');
        const dateValue = `${y}-${m}-${d}`;
        const timeValue = new Intl.DateTimeFormat('ar-EG', {
            hour: '2-digit',
            minute: '2-digit',
            hour12: true,
        }).format(parsed);
        const levelLabel = interview.applicant?.level?.trim() || '';
        const workTypeLabel = interview.applicant?.work_type?.trim() || '';
        return { dateValue, timeValue, levelLabel, workTypeLabel };
    }, [interview]);

    return (
        <div>
            <Dialog open={openUpdateDialog} onOpenChange={setopenUpdateDialog}>
                <DialogContent
                    dir="rtl"
                    showCloseButton={false}
                    className="max-w-[520px] rounded-xl border border-[#E8E7EA] bg-white-blue-50 p-5 sm:p-6"
                >
                    <DialogHeader className="space-y-2">
                        <DialogTitle className="text-right text-[20px] font-semibold text-[#205295]">
                            <div className="flex items-center gap-2">
                                <EyeIcon width="24" height="24" />
                                معاينة المقايلة
                            </div>
                        </DialogTitle>
                        <div className="w-full border-b border-[#E8E7EA]" />
                    </DialogHeader>

                    <div className="mt-2 grid grid-cols-1 gap-3 sm:grid-cols-2">
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">اسم المتقدم</label>
                            <Input value={interviewApplicantName(interview)} readOnly className="h-9 bg-white" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">الوظيفة</label>
                            <Input value={interviewJobTitle(interview)} readOnly className="h-9 bg-white" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">المستوى</label>
                            <Input
                                value={levelLabel}
                                readOnly
                                className="h-9 bg-white"
                                placeholder="—"
                            />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">نوع العمل</label>
                            <Input value={workTypeLabel} readOnly className="h-9 bg-white" placeholder="—" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">التاريخ</label>
                            <Input type="date" value={dateValue} readOnly className="h-9 bg-white" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">الوقت</label>
                            <Input value={timeValue} readOnly className="h-9 bg-white" placeholder="—" />
                        </div>
                    </div>

                    <div className="mt-5 flex justify-start">
                        <PrimaryButton
                            type="button"
                            onClick={() => setopenUpdateDialog(false)}
                            className="h-9 min-w-[120px]"
                        >
                            الغاء
                        </PrimaryButton>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}
