import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { Interview, interviewApplicantName, interviewJobTitle } from '../../types/interview.types';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';

interface InterviewRejectionProps {
    interview: Interview | null;
    openRejectionDialog: boolean;
    setopenRejectionDialog: (open: boolean) => void;
}

export default function InterviewRejection({
    interview,
    openRejectionDialog,
    setopenRejectionDialog,
}: InterviewRejectionProps) {
    return (
        <div>
            <Dialog open={openRejectionDialog} onOpenChange={setopenRejectionDialog}>
                <DialogContent
                    dir="rtl"
                    showCloseButton={false}
                    className="max-w-[760px] rounded-xl border border-[#E8E7EA] bg-white-blue-50 p-4 sm:p-5 max-h-[90vh] overflow-y-auto"
                >
                    <DialogHeader className="space-y-2">
                        <DialogTitle className="text-right text-[22px] sm:text-[26px] font-semibold leading-[32px] sm:leading-[36px] text-[#E03131]">
                            رسالة الرفض
                        </DialogTitle>
                        <div className="w-full border-b border-[#E8E7EA]" />
                    </DialogHeader>

                    <div className="mt-4 rounded-xl border border-[#E5E7EB] bg-white p-3 shadow-[0px_1px_2px_0px_#1018280D]">
                        <div className="flex items-start justify-between gap-3">
                            <div className="text-right">
                                <h3 className="text-base sm:text-lg font-semibold leading-[26px] text-primery-blue-900">
                                    {interviewApplicantName(interview)}
                                </h3>
                                <p className="text-sm sm:text-[15px] text-[#625E74]">{interviewJobTitle(interview)}</p>
                                {interview?.experience_years != null && interview.experience_years > 0 ? (
                                    <p className="text-sm sm:text-[15px] text-[#625E74]">
                                        خبرة {interview.experience_years} سنوات
                                    </p>
                                ) : interview?.applicant?.level ? (
                                    <p className="text-sm sm:text-[15px] text-[#625E74]">
                                        المستوى: {interview.applicant.level}
                                    </p>
                                ) : null}
                            </div>
                            <span className="rounded-md bg-[#EDF8F2] px-2 py-0.5 text-[11px] text-[#1D9D62]">
                                مقابلة
                            </span>
                        </div>
                        {interview?.status ? (
                            <div className="mt-3 text-right text-[11px] text-[#625E74]">
                                الحالة: <span className="font-medium text-primery-blue-900">{interview.status}</span>
                            </div>
                        ) : null}
                    </div>

                    <div className="mt-6">
                        <label className="mb-1.5 block text-right text-lg sm:text-xl font-semibold leading-[30px] text-primery-blue-900">
                            البريد الالكتروني
                        </label>
                        <input
                            type="email"
                            placeholder="ادخل البريد الالكتروني"
                            className="h-[44px] w-full rounded-lg border border-[#E8E7EA] bg-white px-3.5 text-right text-sm text-[#625E74] outline-none placeholder:text-[#CACACA]"
                        />
                    </div>

                    <div className="mt-6">
                        <label className="mb-1.5 block text-right text-lg sm:text-xl font-semibold leading-[30px] text-primery-blue-900">
                            ملاحظات
                        </label>
                        <textarea
                            placeholder="اكتب ملاحظات عن المتقدم"
                            className="h-[130px] w-full resize-none rounded-lg border border-[#E8E7EA] bg-white p-3.5 text-right text-sm text-[#625E74] outline-none placeholder:text-[#CACACA]"
                        />
                    </div>

                    <div className="mt-6 grid grid-cols-1 gap-3 sm:grid-cols-2">
                        <PrimaryButton
                            type="button"
                            className="h-[44px] bg-[#FBE2E2] text-[#C52E2E] hover:bg-[#f4d2d2] text-sm sm:text-base font-medium"
                        >
                            ارسال عبر البريد
                        </PrimaryButton>
                        <PrimaryButton
                            type="button"
                            onClick={() => setopenRejectionDialog(false)}
                            className="h-[44px] border border-[#D0D5DD] bg-transparent text-[#625E74] hover:bg-[#F3F4F6] text-sm sm:text-base font-medium"
                        >
                            إلغاء
                        </PrimaryButton>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}
